  "Our Italian-style coffeehouse and wine bar is the all-day town hall — morning latte to pre-dinner wine. Frequent happy hours bring cocktails, mocktails and complimentary snacks for friends and visitors.": "我们的意式咖啡馆与葡萄酒吧是全天的聚会中心——从早晨的拿铁到晚餐前的葡萄酒。经常举办的欢乐时光为朋友和访客提供鸡尾酒、无酒精饮品和免费小食。",
