  // ---------- Added with the server-side rendering (alt text, metadata, new templates) ----------
  "Prairie City Landing · Luxury Senior Living in Folsom, CA": "Prairie City Landing · 加州福尔瑟姆豪华长者社区",
  "Sacramento County’s award-winning luxury senior living community in Folsom, CA. Independent Living from $5,950 a month, Assisted Living Services and Harbor Memory Care. Not just a home, but a lifestyle.": "萨克拉门托县屡获殊荣的豪华长者社区，位于加州福尔瑟姆。独立生活每月 $5,950 起，另有协助生活服务和 Harbor 记忆护理。这里不只是一个家，更是一种生活方式。",
  "Prairie City Landing’s front entrance under a blue Folsom sky": "福尔瑟姆蓝天下的 Prairie City Landing 正门",
  "Good morning from Folsom. Here’s what’s happening around the community.": "来自福尔瑟姆的早安问候。以下是社区里正在进行的活动。",
  "Good afternoon from Folsom. Here’s what’s happening around the community.": "来自福尔瑟姆的午安问候。以下是社区里正在进行的活动。",
