  "That’s a wrap for today’s calendar. The Rendezvous and Natoma Café are open until {1}.": "今天的活动日历到此结束。The Rendezvous 和 Natoma Café 营业至{1}。",
  "That’s a wrap for today. Here’s what’s on tomorrow.": "今天的活动到此结束。以下是明天的安排。",
  "See {1} more today and the full calendar": "查看今天另外 {1} 项活动及完整日历",
  "The Rendezvous bar with its espresso machine and wine shelves": "The Rendezvous 吧台，配有意式咖啡机和酒架",
  "The Cypress Room set with white tablecloths": "铺着白色桌布的 The Cypress Room",
  "Up next": "即将开始",
