  "until {1}": "至{1}",
  "Independent Living from {1} a month, Assisted Living Services delivered in every apartment, and Harbor Memory Care at Prairie City Landing in Folsom, CA.": "加州福尔瑟姆 Prairie City Landing：独立生活每月 {1} 起，每套公寓均可享协助生活服务，另有 Harbor 记忆护理。",
  "A sunlit apartment dining area set for two": "阳光充足的公寓用餐区，摆好了两人餐具",
  "Luxury Independent Living apartments up to {1} sq ft in Folsom, CA, from {2} a month. Full kitchens, in-apartment washer and dryer, no second-person fee, and pets welcome.": "加州福尔瑟姆的豪华独立生活公寓，面积最大 {1} 平方英尺，每月 {2} 起。配备全功能厨房和室内洗衣机、烘干机，不收第二人费用，欢迎携带宠物。",
  "A kitchen with stainless appliances, pendant lights and a breakfast bar": "配有不锈钢电器、吊灯和早餐吧台的厨房",
  "Residents enjoying lunch together on the courtyard patio": "住户们在庭院露台上一起享用午餐",
  "A one-bedroom apartment with a view from the living room into the bedroom": "一居室公寓，从客厅望向卧室",
  "A bright living room open to the kitchen": "与厨房相通的明亮客厅",
  "A full-size kitchen with stainless appliances and a peninsula": "配有不锈钢电器和半岛台的全尺寸厨房",
  "A bedroom with a large window and soft light": "大窗户、光线柔和的卧室",
  "A dining area set for guests": "为客人摆好餐具的用餐区",
  "A bathroom with a walk-in shower": "带无障碍淋浴间的浴室",
  "A second bedroom with a blue feature wall": "带蓝色装饰墙的次卧",
  "Assisted Living Services delivered discreetly in every apartment at Prairie City Landing, Folsom. {1} a month base support fee plus personal care by care plan — you never have to move.": "福尔瑟姆 Prairie City Landing 的每套公寓都能低调贴心地提供协助生活服务。每月基本支持费 {1}，另按护理计划提供个人护理——您永远不必搬家。",
  "A Care Partner walking with a resident in the garden": "护理伙伴陪同住户在花园散步",
  "Harbor Memory Care at Prairie City Landing, Folsom: an environment of youthful optimism, with its own Events & Adventures, weekly outings and a secured courtyard. Studios from {1} a month.": "福尔瑟姆 Prairie City Landing 的 Harbor 记忆护理：充满青春乐观气息的环境，拥有专属的活动与探险、每周外出活动和安全庭院。单间公寓每月 {1} 起。",
  "A resident and team member stand-up paddling on the lake": "一位住户和一位团队成员在湖上玩站立式桨板",
  "Life at Prairie City Landing is YUSM — Youthful, Useful, Spontaneous and Mobile. Explore the activity calendar, dining, fitness, Events & Adventures and our amazing spaces.": "Prairie City Landing 的生活就是 YUSM——年轻（Youthful）、有用（Useful）、随性（Spontaneous）、灵活（Mobile）。欢迎浏览活动日历、餐饮、健身、活动与探险以及我们的精彩空间。",
  "Residents celebrating Lunar New Year with lion dancers": "住户们与舞狮队一起欢度农历新年",
  "Prairie City Landing is owned, designed, built and run by Tenfold Senior Living. Our purpose, our six values, and the awards that recognize our team.": "Prairie City Landing 由 Tenfold Senior Living 拥有、设计、建造和运营。在这里了解我们的宗旨、六大价值观，以及我们团队荣获的奖项。",
  "Two residents laughing together on a sofa": "两位住户坐在沙发上开怀大笑",
  "A Care Partner and resident sharing a laugh": "护理伙伴与住户一起欢笑",
  "The Prairie City Landing courtyard with palms and umbrellas": "Prairie City Landing 庭院，棕榈树与遮阳伞",
  "Prairie City Landing is SageCare certified and committed to diversity, equity and inclusion. ASL interpreters are available for tours, care conferences and events.": "Prairie City Landing 已获得 SageCare 认证，致力于多元、平等与包容。参观、护理会议和活动均可提供美国手语（ASL）翻译。",
  "A couple tending flowers together in the garden": "一对伴侣在花园里一起照料花草",
  "Two people holding hands across a café table": "两人隔着咖啡桌牵手",
  "Our buildings, website and printed calendars are designed for everyone. Use the text size and contrast controls at the top of every page, or the language links to read this site in Spanish or Simplified Chinese (中文).": "我们的建筑、网站和印刷版日历都为每个人而设计。您可以使用每个页面顶部的字体大小和对比度控件，或通过语言链接以西班牙语或简体中文（中文）阅读本网站。",
  "Take a photo tour of Prairie City Landing: three restaurants, a theatre, art studio, fitness center, salon, Club Room, Living Room library and a courtyard with a fire table and bocce.": "通过照片参观 Prairie City Landing：三家餐厅、剧院、艺术工作室、健身中心、美发沙龙、Club Room、Living Room 图书室，以及设有火盆桌和地掷球场的庭院。",
