  "Studio, one- and two-bedroom apartments from {1} a month, Assisted Living Services in every apartment, and Harbor Memory Care. No second-person fee.": "单间公寓、一居室和两居室每月 {1} 起，每套公寓均可享协助生活服务，另有 Harbor 记忆护理。不收第二人费用。",
