  "monthly base support fee, plus personal care by care plan. Jan McLennon, our Resident Services Director, completes a pre-move-in assessment with you and your family.": "，另按护理计划提供个人护理。我们的住户服务总监 Jan McLennon 会在入住前与您和您的家人一起完成评估。",
