  "floor plan and virtual tour": "户型图与虚拟参观",
  "Ten friendly questions to see whether Independent Living, Assisted Living Services or Harbor Memory Care is the right fit.": "回答十个简单的问题，看看独立生活、协助生活服务还是 Harbor 记忆护理最适合。",
  "Their first name (optional)": "对方的名字（选填）",
  "your mother": "您的母亲",
  "your father": "您的父亲",
  "your partner": "您的伴侣",
  "your loved one": "您的亲人",
  "Where is {name} living right now?": "{name}目前住在哪里？",
  "How are medications going for {name}?": "{name}的用药情况如何？",
  "What about bathing and getting dressed, for {name}?": "{name}洗澡和穿衣的情况如何？",
  "And meals? Which sounds most like {name}?": "饮食方面呢？哪一项最符合{name}的情况？",
  "How does {name} get around?": "{name}平时如何行动？",
  "Have there been changes in memory for {name}?": "{name}的记忆力有变化吗？",
  "What are nights like for {name}?": "{name}夜间的情况如何？",
  "How’s {name}’s social life these days?": "{name}最近的社交生活如何？",
  "What would {name} love to have more of?": "{name}希望生活中多些什么？",
  "Our suggestion for {name}": "我们给{name}的建议",
  "could make every day easier": "能让每一天都更轻松",
  "may be the right place": "可能是合适的选择",
  "{Name} sounds independent and ready to enjoy more of life, with none of the chores. Independent Living means a real apartment home, three restaurants, a calendar full of things to do, and our team on site {1} hours, just in case.": "{Name}听起来生活独立，准备好摆脱家务、更好地享受生活。独立生活意味着一个真正的公寓之家、三家餐厅、排得满满的活动日历，以及 {1} 小时驻场的团队，以备不时之需。",
  "You’d have your own apartment and your own routine, with a Care Partner close by for the parts of the day that have become harder. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "您将拥有自己的公寓和自己的生活节奏，日常中变得吃力的环节，都有护理伙伴在身边帮忙。协助生活服务在每套公寓中都能低调贴心地提供，因此任何人都不必为了获得更多帮助而搬家。",
  "You’d have your own apartment and your own routine, with a Care Partner close by for the parts of the day that have become harder, from medications to bathing. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "您将拥有自己的公寓和自己的生活节奏，从用药到洗澡，日常中变得吃力的环节，都有护理伙伴在身边帮忙。协助生活服务在每套公寓中都能低调贴心地提供，因此任何人都不必为了获得更多帮助而搬家。",
  "{Name} would have an apartment and a routine of their own, with a Care Partner close by for the parts of the day that have become harder. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "{Name}将拥有自己的公寓和自己的生活节奏，日常中变得吃力的环节，都有护理伙伴在身边帮忙。协助生活服务在每套公寓中都能低调贴心地提供，因此任何人都不必为了获得更多帮助而搬家。",
  "{Name} would have an apartment and a routine of their own, with a Care Partner close by for the parts of the day that have become harder, from medications to bathing. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "{Name}将拥有自己的公寓和自己的生活节奏，从用药到洗澡，日常中变得吃力的环节，都有护理伙伴在身边帮忙。协助生活服务在每套公寓中都能低调贴心地提供，因此任何人都不必为了获得更多帮助而搬家。",
  "You’d live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love: weekly outings, music, gardening and purposeful roles in everyday life.": "您将住在 Harbor——我们安全而温馨如家的记忆护理社区，拥有专属庭院和专属团队。Harbor 围绕住户仍然能做、仍然热爱的事情而打造：每周外出活动、音乐、园艺，以及在日常生活中承担有意义的角色。",
  "You’d live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love, and families tell us the peace of mind comes quickly: weekly outings, music, gardening and purposeful roles in everyday life.": "您将住在 Harbor——我们安全而温馨如家的记忆护理社区，拥有专属庭院和专属团队。Harbor 围绕住户仍然能做、仍然热爱的事情而打造，家属们告诉我们，他们很快就能安心：每周外出活动、音乐、园艺，以及在日常生活中承担有意义的角色。",
  "{Name} would live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love: weekly outings, music, gardening and purposeful roles in everyday life.": "{Name}将住在 Harbor——我们安全而温馨如家的记忆护理社区，拥有专属庭院和专属团队。Harbor 围绕住户仍然能做、仍然热爱的事情而打造：每周外出活动、音乐、园艺，以及在日常生活中承担有意义的角色。",
