  "Here, friends are as close as the Rendezvous: morning coffee, happy hour, Monday trivia and the Friday Activity Meeting, where residents shape next week’s calendar.": "在这里，朋友就在 The Rendezvous 等着您：早晨的咖啡、欢乐时光、周一知识问答，还有周五的活动会议，由住户们一起决定下周的日历。",
  "{name} and your family": "{name}及您的家人",
  "Compare what staying at home really costs each month with life at Prairie City Landing, from {1} a month with no second-person fee.": "比较一下住在家中每月的实际花费与 Prairie City Landing 的生活费用——每月 {1} 起，不收第二人费用。",
