  "{1} hours a week": "每周 {1} 小时",
  "The two come out about the same": "两者费用大致相当",
  "That’s {1} a year, and it buys three restaurants, a {2}-hour team, weekly housekeeping, transportation and a calendar full of things to do, for both of you, with no second-person fee.": "每年相差 {1}，而这笔费用包含三家餐厅、{2} 小时值守的团队、每周家政清洁、交通服务和排得满满的活动日历，两位都能享受，不收第二人费用。",
  "And at Prairie City Landing, the housekeeping, maintenance, transportation and calendar come with it.": "而在 Prairie City Landing，家政清洁、维修保养、交通服务和活动日历都已包含在内。",
  "Book an in-person or video tour of Prairie City Landing in Folsom with Community Relations Director Cynthia Bazin. Lunch is on us.": "与社区关系部总监 Cynthia Bazin 预约实地或视频参观福尔瑟姆的 Prairie City Landing。午餐由我们招待。",
