  "Free guides to choosing and paying for senior living: care options, costs, funding sources, insurance, VA Aid and Attendance, safety and staying social.": "关于选择长者社区及支付费用的免费指南：护理选择、费用、资金来源、保险、退伍军人事务部（VA）Aid and Attendance 津贴、安全以及保持社交。",
