  "Inside the guide": "指南内容",
  "Questions as you read? Cynthia Bazin, our Community Relations Director, is happy to talk them through at {1}, ext. {2}.": "阅读时有疑问吗？我们的社区关系部总监 Cynthia Bazin 很乐意为您解答，请致电 {1}，分机 {2}。",
  "Back to the guides": "返回指南列表",
  "Frequently Asked Questions": "常见问题",
  "Answers about living at Prairie City Landing: what’s included, care, pets, visiting, parking, mail, moving in and the community fee.": "关于在 Prairie City Landing 生活的解答：包含哪些服务、护理、宠物、探访、停车、邮件、入住以及社区费。",
  "Join the team at Prairie City Landing in Folsom. Open positions for Care Partners, Med Techs, cooks, servers and more, with medical, 401(k) match, tuition assistance and a free meal every shift.": "加入福尔瑟姆 Prairie City Landing 的团队。现招聘护理伙伴、给药技术员、厨师、餐厅服务员等职位，提供医疗保险、401(k) 配比、学费资助，每个班次还提供免费餐食。",
  "A Care Partner walking with a resident outdoors": "护理伙伴陪同住户在户外散步",
