  "Prairie City Landing’s accessibility statement: our WCAG 2.1 AA goal, text size, contrast and language tools, ASL interpreters and large-print calendars.": "Prairie City Landing 无障碍声明：我们的 WCAG 2.1 AA 目标、字体大小、对比度和语言工具、美国手语（ASL）翻译以及大字版日历。",
  "Read the site in English, Español or 中文 (Simplified Chinese): choose from the language links at the top of every page.": "您可以用 English、Español 或中文（简体中文）阅读本网站：请在每个页面顶部的语言链接中选择。",
