  "Roasted Pear Salad": "烤梨沙拉",
  "Butter lettuce, gorgonzola, candied pecans, champagne vinaigrette": "奶油生菜、戈贡佐拉奶酪、糖渍山核桃、香槟油醋汁",
  "Crab Cake": "蟹饼",
