  "Bacon, chicken-apple sausage, hash browns, toast, fruit, tomato, avocado": "培根、鸡肉苹果香肠、薯饼、吐司、水果、番茄、牛油果",
  "Cobb Salad": "科布沙拉",
  "Grilled chicken, bacon, egg, avocado, blue cheese, tomato": "烤鸡肉、培根、鸡蛋、牛油果、蓝纹奶酪、番茄",
  "A cup of soup and half a sandwich or small salad": "一杯汤，配半份三明治或一小份沙拉",
  "The Bruceville Burger": "The Bruceville 汉堡",
  "On a brioche bun · veggie patty available": "布里欧修面包 · 可选素肉饼",
