  "Pastry of the day: Pear Danish": "今日糕点：梨子丹麦酥",
  "Biscotti": "意式脆饼",
  "Prosciutto & Fig Panini": "意式风干火腿无花果帕尼尼",
  "Prosciutto, fig jam, fontina, arugula": "意式风干火腿、无花果酱、芳提娜奶酪、芝麻菜",
  "like the resident who toured the Aerospace Museum": "比如那位参观航空航天博物馆的住户",
  "and found planes he once flew. Every Friday at the Activity Meeting, residents and our Events & Adventures Director go over next week’s calendar, pitch new ideas and settle the details over drinks and appetizers.": "，竟在那里看到了自己当年驾驶过的飞机。每周五的活动会议上，住户们和我们的活动与探险总监一起过一遍下周的日历，提出新点子，并边享用饮品和开胃小食边敲定细节。",
  "Timothy leads the Events & Adventures team and the calendar of classes, clubs, outings and celebrations.": "Timothy 带领活动与探险团队，负责课程、俱乐部、出游和庆祝活动的日历安排。",
  "All trips leave from the Lobby. Seats are limited — sign up at the front desk or with Timothy.": "所有出游均从大堂出发。名额有限——请在前台或向 Timothy 报名。",
  "Dinner Trip: Old Town Elk Grove": "晚餐出游：埃尔克格罗夫老城",
  "Bus Trip: Sandhill Cranes at Stone Lakes National Wildlife Refuge": "大巴出游：Stone Lakes 国家野生动物保护区观赏沙丘鹤",
  "Fast Food Friday: Burgers in Laguna": "周五快餐日：Laguna 吃汉堡",
  "Bus Trip: Old Sacramento & California State Railroad Museum": "大巴出游：萨克拉门托老城与加州铁路博物馆",
  "From everyday enjoyment to once-in-a-lifetime bucket list items: trips, outings, parties and adventures at Bruceville Point in Elk Grove, CA.": "从日常乐趣到一生一次的心愿清单：加州埃尔克格罗夫 Bruceville Point 的旅行、出游、派对和探险。",
  "Events and Adventures Director": "活动与探险总监",
  "Open photo: Paint and Sip": "打开照片：品酒绘画会（Paint and Sip）",
