  ". Most care services are included, and additional care level rates are set by a personal assessment with Amrita Sapkota, our Harbor Director.": "。大部分护理服务已包含在内，额外护理等级费用由 Harbor 总监 Amrita Sapkota 进行个人评估后确定。",
