  "Your apartment, your schedule, your choices. Cook in your own kitchen or dine in one of our restaurants, join an outing or enjoy a quiet afternoon, and come and go as you please.": "您的公寓、您的日程、您的选择。在自己的厨房做饭，或到我们的餐厅用餐；参加出游，或享受一个安静的下午；来去自由。",
  "No second-person fee for couples, Assisted Living Services if and when you want them, and a team that listens before it acts. That’s what we mean by Different By Design.": "夫妻入住无需支付第二人费用，可随时按需选择协助生活服务，团队先倾听再行动。这就是我们所说的 Different By Design（与众不同，源于设计）。",
