  "Luxury senior living in Folsom and Elk Grove, California: spacious apartments, Assisted Living Services in every apartment, Harbor Memory Care and a lifestyle that keeps you youthful, useful, spontaneous and mobile.": "位于加州福尔瑟姆和埃尔克格罗夫的豪华长者社区：宽敞的公寓、每套公寓均可享受协助生活服务、Harbor 记忆护理，以及让您保持年轻、有用、随性和灵活的生活方式。",
  "Our communities": "我们的社区",
  "Two open communities in Sacramento County, each with Independent Living, Assisted Living Services and Harbor Memory Care.": "萨克拉门托县的两个已开放社区，均提供独立生活、协助生活服务和 Harbor 记忆护理。",
  "Real apartment homes, not rooms. Bring the dining table, the sectional and the art you love.": "真正的公寓住宅，而不只是房间。带上您的餐桌、组合沙发和心爱的艺术品。",
  "Harbor is a home-like, secured neighborhood within each community, with its own courtyard, its own activity team and its own Events & Adventures calendar.": "Harbor 是每个社区内温馨如家、安全封闭的居住区，拥有自己的庭院、自己的活动团队和自己的活动与探险日历。",
  "The lifestyle": "生活方式",
  "YUSM is the philosophy behind every Tenfold calendar, menu and class. It’s how we help residents keep living fully.": "YUSM 是每一份 Tenfold 日历、菜单和课程背后的理念，也是我们帮助住户继续充实生活的方式。",
